// v24.xx (sndA2), HIS ORDER 2026-10-12 (improve the sound, a distinct noise for every action): THE BLAST. Every explosive (a Frag
// Charge, a tripwire mine, a Howler shell, a cook-off, the death beat) played one 0.18 s burst of noise through a 380 Hz lowpass, the
// same near and far, only quieter: no crack, no weight, and soft on laptop speakers. Now distance shapes it the way it shapes the
// guns (gunLayers). CLOSE (under 350, or in your own hands): a bright crack that falls straight into the body (one noise whose lowpass
// drops from 4.2 kHz to 260 Hz in 0.14 s), a sub drop from 90 to 35 Hz and a scatter of debris 0.12 s later. MIDDLE: the same without
// the debris, duller. FAR (over 700): only a dull 60 Hz thump and, a beat later, a low rolling rumble. A TRIPWIRE MINE is told apart:
// the wire snaps and the mine clicks 80 ms before it goes, so a wire going off across the map is a wire. The ducks of v23.69 stand.
// About 8 nodes close, 5 far; one blast per 40 ms. The noise buffers stay at 6000 samples and are slowed to length (the v10.56 rule).
function sndABoom(a,OUT,vol,t,d,kind){
  var near=!(d>=350), far=d>700, t0=t, n=6000, b, c, i, s, f, g;
  if(!sndAGate('boom',0.04,t)) return;
  if(kind==='wire'){
    sndATone(a,OUT,'triangle',4000,2500,0.06,0.08*vol,t);
    sndANoise(a,OUT,{dur:0.008,pw:1.5,ft:'bandpass',f0:1800,q:2.5,g:0.25*vol,at:t+0.02});
    t0=t+0.08;
  }
  b=a.createBuffer(1,n,a.sampleRate); c=b.getChannelData(0);
  for(i=0;i<n;i++) c[i]=(Math.random()*2-1)*Math.pow(1-i/n,far?1.4:2.2);
  s=a.createBufferSource(); s.buffer=b;
  f=a.createBiquadFilter(); f.type='lowpass'; f.Q.value=0.8;
  g=a.createGain();
  if(far){
    // the thump that carries, and the rumble a beat behind it
    sndATone(a,OUT,'sine',60,38,0.28,0.34*vol,t0);
    if(s.playbackRate) s.playbackRate.value=0.15;
    f.frequency.setValueAtTime(200,t0);
    g.gain.value=0.32*vol;
    s.connect(f); f.connect(g); g.connect(OUT); s.start(t0+0.09);
    return;
  }
  // the crack falling into the body
  if(s.playbackRate) s.playbackRate.value=near?0.22:0.26;
  f.frequency.setValueAtTime(near?4200:1600,t0); f.frequency.exponentialRampToValueAtTime(260,t0+0.14);
  g.gain.value=(near?0.42:0.34)*vol;
  s.connect(f); f.connect(g); g.connect(OUT); s.start(t0);
  // the sub drop
  sndATone(a,OUT,'sine',near?90:70,35,0.35,(near?0.55:0.4)*vol,t0);
  // the debris, close only
  if(near) sndANoise(a,OUT,{dur:0.2,pw:1.4,ft:'highpass',f0:3200,q:0.7,g:0.07*vol,at:t0+0.12});
}
